class UI {
  constructor(game) {
    this.game = game;
    this.selectedCrew = 0;
    this.bootProgress = 0;
    this.markers = new Map();
    this.settings = this.loadSettings();
    this.lastHUDFlush = 0;
    this.cache = {};
    this.menuOpen = true;
    this.pauseOpen = false;
    this.mapOpen = false;
    this.settingsOpen = false;
    this.merchantOpen = false;
    this.settingsReturn = 'menu';
    this.buildItems = [];
    this.currentPlanetId = null;
    this.objectiveKey = '';
    this.overlayLock = false;
    this.bind();
    this.buildBuildBar();
    this.applySettingsToDOM();
    this.setCrew(0, false);
    this.setMode('surface');
    this.setInteraction({ visible: false });
    this.updateAmmo(12, 48, false);
    this.updateVitals(100, 100);
    this.setResources({ alloy: 16, fiber: 8, crystal: 6, stardust: 2 });
    this.bodyClass('is-touch', this.isTouch());
    if (this.isTouch()) {
      document.querySelector('.hero-footnote')?.classList.add('hidden');
    }
    this.emitSettings();
  }

  enterLandscape() {
    if (!this.isTouch()) return;
    // 桌面（哪怕带触摸屏的笔电）绝不请求全屏：进出全屏会重排画布，看起来就是闪屏
    if (this._landscapeTried) return;
    this._landscapeTried = true;
    const lock = () => {
      try { screen.orientation?.lock?.('landscape').catch(() => {}); } catch (e) { /* ignore */ }
    };
    if (!document.fullscreenElement && document.documentElement.requestFullscreen) {
      document.documentElement.requestFullscreen().then(lock).catch(lock);
    } else {
      lock();
    }
  }

  isTouch() {
    return matchMedia('(pointer: coarse)').matches;
  }

  bodyClass(name, on) {
    document.body.classList.toggle(name, !!on);
  }

  setMenuLive(live) {
    // Only reveal the WebGL canvas after the menu scene has rendered at least
    // one frame. The static cover stays underneath as an instant fallback.
    this.bodyClass('menu-live', !!live);
  }

  loadSettings() {
    let saved = {};
    try { saved = JSON.parse(localStorage.getItem('starweaver.settings.v2') || '{}'); } catch (e) { saved = {}; }
    return {
      quality: saved.quality || 'medium',
      sensitivity: saved.sensitivity ?? 1.0,
      volume: saved.volume ?? 0.55,
      shake: saved.shake ?? true,
      cine: saved.cine ?? true,
    };
  }

  saveSettings() {
    localStorage.setItem('starweaver.settings.v2', JSON.stringify(this.settings));
  }

  applySettingsToDOM() {
    $$('#quality-seg button').forEach((b) => b.classList.toggle('selected', b.dataset.quality === this.settings.quality));
    $('#sens-range').value = this.settings.sensitivity;
    $('#sens-value').textContent = Number(this.settings.sensitivity).toFixed(2);
    $('#vol-range').value = this.settings.volume;
    $('#vol-value').textContent = Math.round(this.settings.volume * 100);
    $('#shake-toggle').classList.toggle('on', this.settings.shake);
    $('#cine-toggle').classList.toggle('on', this.settings.cine);
  }

  emitSettings() {
    this.game?.applySettings?.(this.settings);
  }

  bind() {
    const hintEl = $('#rotate-hint');
    hintEl?.addEventListener('pointerdown', (e) => { e.preventDefault(); this.enterLandscape(); });
    hintEl?.addEventListener('click', (e) => { e.preventDefault(); this.enterLandscape(); });
    $('#start-btn').addEventListener('click', () => {
      this.game?.audio?.uiConfirm?.();
      this.game?.startNewGame?.();
    });
    $('#continue-btn').addEventListener('click', () => {
      this.game?.audio?.uiConfirm?.();
      this.game?.continueGame?.();
    });
    $$('#crew-cards .crew-card').forEach((card) => {
      card.addEventListener('click', () => {
        this.setCrew(Number(card.dataset.crew), true);
        this.game?.audio?.ui?.();
      });
    });
    $('#menu-sound').addEventListener('click', () => {
      this.game?.toggleMute?.();
      this.updateSoundButton();
    });
    $('#menu-settings').addEventListener('click', () => this.openSettings('menu'));
    $('#settings-close').addEventListener('click', () => this.closeSettings());
    $('#settings-done').addEventListener('click', () => this.closeSettings());
    $('#pause-settings').addEventListener('click', () => this.openSettings('pause'));
    $('#resume-btn').addEventListener('click', () => this.closePause(true));
    $('#pause-save').addEventListener('click', () => {
      this.game?.saveGame?.(true);
      this.showNotification('航程已保存至本机', 'success');
    });
    $('#return-menu').addEventListener('click', () => {
      this.closePause(false);
      this.game?.returnToMenu?.();
    });
    $('#btn-menu').addEventListener('click', () => this.openPause());
    $('#btn-scan').addEventListener('click', () => this.game?.scanCreature?.());
    $('#btn-map').addEventListener('click', () => this.openStarmap());
    $('#starmap-close').addEventListener('click', () => this.closeStarmap());
    $('#starmap-canvas')?.addEventListener('pointerdown', (e) => this.pickMapPlanet(e));
    $('#btn-build').addEventListener('click', () => this.game?.toggleBuildMode?.());
    $('#build-confirm').addEventListener('click', () => this.game?.confirmBuildPlacement?.());
    $('#build-rotate').addEventListener('click', () => this.game?.building?.rotate?.(0.45));
    $('#build-exit').addEventListener('click', () => this.game?.toggleBuildMode?.(false));
    $('#map-set-course')?.addEventListener('click', () => {
      if (!this.mapPlanetId) return;
      const ok = this.game?.setCourse?.(this.mapPlanetId);
      if (ok) {
        this.showToast(`航向已锁定 · ${this.planetName(this.mapPlanetId)}`);
        this.updateMapCourseButton(true);
      }
    });
    $$('#orbital-map .map-planet').forEach((p) => {
      p.addEventListener('click', () => {
        this.mapPlanetId = p.dataset.planet;
        this.updateMapPlanet(this.mapPlanetId);
        this.game?.audio?.ui?.();
      });
    });
    $('#scan-close').addEventListener('click', () => this.hideScan());
    $('#merchant-close').addEventListener('click', () => this.game?.closeMerchant?.());
    $('#merchant-sell-list').addEventListener('click', (e) => {
      const btn = e.target.closest('[data-sell]');
      if (btn) this.game?.sellResource?.(btn.dataset.sell);
    });
    $('#merchant-buy-list').addEventListener('click', (e) => {
      const btn = e.target.closest('[data-buy]');
      if (btn) this.game?.buyMerchantStock?.(btn.dataset.buy);
    });
    $('#respawn-btn').addEventListener('click', () => this.game?.respawn?.());
    // 死亡字卡返回：先解指针锁，再调 returnToMenu；万一 returnToMenu 抛错就强制回封面
    const bailToMenu = () => {
      document.exitPointerLock?.();
      this._clearDeathAutoReturn?.();
      // 先立刻给反馈：把字卡收掉、露出“正在返回”，再做可能很慢的 returnToMenu
      const cards = ['#station-crash', '#sun-death', '#storm-death', '#blackhole-death'];
      let hadCard = false;
      cards.forEach((s) => {
        const el = $(s);
        if (el && !el.classList.contains('hidden')) {
          hadCard = true;
          el.classList.add('hidden');
          el.classList.remove('visible');
        }
      });
      if (hadCard) {
        if (this._returning) return;
        this._returning = true;
        setTimeout(() => {
          this._returning = false;
          doReturn();
        }, 0);
        return;
      }
      doReturn();
    };
    const doReturn = () => {
      try {
        this.game?.returnToMenu?.();
      } catch (err) {
        console.warn('[ui] returnToMenu 失败，强制回封面：', err);
        try {
          const g = this.game;
          if (g) { g.mode = 'menu'; g.overlayOpen = false; g.paused = false; }
          this.setBlackHoleDeathFade(false);
          ['#station-crash', '#sun-death', '#storm-death', '#blackhole-death'].forEach((s) => {
            const el = $(s);
            if (el) { el.classList.add('hidden'); el.classList.remove('visible'); }
          });
          this.hideHUD();
          this.showMenu({ hasSave: true });
        } catch (err2) {
          console.warn('[ui] 强制回封面也失败：', err2);
        }
      }
    };
    this._bailToMenu = bailToMenu;
    // pointerdown + click 双绑：pointer lock 还没释放时 click 会被吞掉，pointerdown 更早
    const bindDeathButton = (sel) => {
      const el = $(sel);
      if (!el) return;
      el.addEventListener('pointerdown', (e) => { e.preventDefault(); e.stopPropagation(); bailToMenu(); });
      el.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); bailToMenu(); });
    };
    bindDeathButton('#blackhole-death-menu');
    bindDeathButton('#storm-death-menu');
    bindDeathButton('#sun-death-menu');
    bindDeathButton('#station-crash-menu');
    // 兜底 2：捕获阶段监听全窗口点击。字卡出来 400ms 后，点画面任何位置都算“继续”
    window.addEventListener('pointerdown', (e) => {
      if (performance.now() < (this._cardGuardUntil || 0)) return;
      const locked = $('#station-locked');
      if (locked && !locked.classList.contains('hidden')) {
        this.game?.closeStation?.();
        return;
      }
      const ids = ['#station-crash', '#sun-death', '#storm-death', '#blackhole-death'];
      const open = ids.some((s) => { const el = $(s); return el && !el.classList.contains('hidden'); });
      if (!open) return;
      bailToMenu();
    }, true);
    // 兜底：指针被锁住时鼠标点不到按钮，Esc/Enter/空格 直接回主菜单
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape' && e.key !== 'Enter' && e.key !== ' ') return;
      const locked = $('#station-locked');
      if (locked && !locked.classList.contains('hidden')) {
        e.preventDefault();
        this.game?.closeStation?.();
        return;
      }
      const ids = ['#station-crash', '#sun-death', '#storm-death', '#blackhole-death'];
      const open = ids.some((s) => { const el = $(s); return el && !el.classList.contains('hidden'); });
      if (!open) return;
      e.preventDefault();
      bailToMenu();
    });
    $('#station-locked-btn')?.addEventListener('click', () => this.game?.closeStation?.());
    $('#menu-sound').addEventListener('click', () => this.updateSoundButton());

    // quality
    $$('#quality-seg button').forEach((b) => {
      b.addEventListener('click', () => {
        this.settings.quality = b.dataset.quality;
        $$('#quality-seg button').forEach((x) => x.classList.toggle('selected', x === b));
        this.saveSettings();
        this.emitSettings();
        this.game?.audio?.ui?.();
      });
    });
    $('#sens-range').addEventListener('input', (e) => {
      this.settings.sensitivity = Number(e.target.value);
      $('#sens-value').textContent = this.settings.sensitivity.toFixed(2);
      this.saveSettings();
      this.emitSettings();
    });
    $('#vol-range').addEventListener('input', (e) => {
      this.settings.volume = Number(e.target.value);
      $('#vol-value').textContent = Math.round(this.settings.volume * 100);
      this.saveSettings();
      this.emitSettings();
    });
    $('#shake-toggle').addEventListener('click', () => {
      this.settings.shake = !this.settings.shake;
      $('#shake-toggle').classList.toggle('on', this.settings.shake);
      this.saveSettings();
      this.emitSettings();
    });
    $('#cine-toggle').addEventListener('click', () => {
      this.settings.cine = !this.settings.cine;
      $('#cine-toggle').classList.toggle('on', this.settings.cine);
      this.saveSettings();
      this.emitSettings();
    });
    // build items event delegation
    $('#build-items').addEventListener('click', (e) => {
      const item = e.target.closest('.build-item');
      if (!item) return;
      this.game?.selectBuild?.(item.dataset.build);
      this.game?.audio?.ui?.();
    });
    // UI hover sounds and pointer cursor
    document.addEventListener('pointerover', (e) => {
      if (e.target.closest('button')) this.game?.audio?.ui?.();
    });
    document.addEventListener('pointerdown', () => {
      if (this.game?.audio && !this.game.audio.ready) this.game.audio.init();
    });
    window.addEventListener('keydown', (e) => {
      if (e.code === 'Escape') {
        if (this.merchantOpen) { this.game?.closeMerchant?.(); e.preventDefault(); }
        else if (this.mapOpen) { this.closeStarmap(); e.preventDefault(); }
        else if (this.settingsOpen) { this.closeSettings(); e.preventDefault(); }
        else if (this.pauseOpen) { this.closePause(true); e.preventDefault(); }
        else if (this.game?.buildMode) { this.game.toggleBuildMode(false); e.preventDefault(); }
        else if (this.game?.isPlayingState?.()) { this.openPause(); e.preventDefault(); }
      }
    });
    // tooltips via title already.
    this.updateSoundButton();
  }

  updateSoundButton() {
    const btn = $('#menu-sound');
    if (!btn) return;
    btn.textContent = this.game?.muted ? '◍' : '◌';
    btn.classList.toggle('off', !!this.game?.muted);
    btn.title = this.game?.muted ? '取消静音' : '静音';
  }

  setCrew(index, notify = true) {
    this.selectedCrew = clamp(index, 0, 2);
    $$('#crew-cards .crew-card').forEach((card, i) => card.classList.toggle('selected', i === this.selectedCrew));
    localStorage.setItem('starweaver.crew', String(this.selectedCrew));
    if (notify && this.game?.onCrewSelected) this.game.onCrewSelected(this.selectedCrew);
  }

  getSavedCrew() {
    const v = Number(localStorage.getItem('starweaver.crew'));
    return Number.isFinite(v) ? clamp(v, 0, 2) : 0;
  }

  setBootProgress(p, label = '') {
    this.bootProgress = clamp(p, 0, 1);
    $('#boot-progress-fill').style.width = `${Math.round(this.bootProgress * 100)}%`;
    if (label) $('#boot-readout').textContent = label;
    else $('#boot-readout').textContent = `CALIBRATING ATMOSPHERES · ${String(Math.round(this.bootProgress * 100)).padStart(2, '0')}%`;
  }

  finishBoot() {
    this.setBootProgress(1, 'READY FOR DEPARTURE · 100%');
    // The loading screen has done its job. Hide it synchronously after the
    // prewarm render; a timer here can be delayed by the first heavy frame and
    // leave a translucent overlay sitting over the title screen.
    const boot = $('#boot');
    boot.classList.add('is-ready', 'hidden');
  }

  showMenu({ hasSave = false } = {}) {
    this.menuOpen = true;
    this.bodyClass('menu-live', false);
    this.bodyClass('menu-active', true);
    this.bodyClass('playing', false);
    this.bodyClass('mode-space', false);
    const menu = $('#menu');
    menu.classList.remove('hidden', 'is-out');
    $('#continue-btn').classList.toggle('hidden', !hasSave);
    const crew = this.getSavedCrew();
    this.setCrew(crew, false);
    $('#hud').classList.add('hidden');
    $('#cinematic-title').classList.remove('visible');
    $('#starmap').classList.add('hidden');
    $('#pause').classList.add('hidden');
    $('#settings').classList.add('hidden');
    $('#merchant').classList.add('hidden');
    $('#death').classList.add('hidden');
    $('#gravity-warning').classList.add('hidden');
    $('#gravity-warning').classList.remove('visible');
    $('#blackhole-death').classList.add('hidden');
    $('#blackhole-death').classList.remove('visible');
    $('#blackhole-death-fade').classList.remove('active');
    $('#space-hud').classList.add('hidden');
    $('#build-bar').classList.add('hidden');
    $('#weapon-panel').style.opacity = '';
    $('.vitals-panel').style.opacity = '';
    this.mapOpen = false;
    this.pauseOpen = false;
    this.settingsOpen = false;
    this.merchantOpen = false;
    this.bodyClass('merchant-open', false);
    this.bodyClass('aiming', false);
    this.bodyClass('build-mode', false);
  }

  hideMenu() {
    if (!this.menuOpen) return;
    this.menuOpen = false;
    const menu = $('#menu');
    menu.classList.add('is-out');
    this.bodyClass('menu-live', false);
    this.bodyClass('menu-active', false);
    setTimeout(() => menu.classList.add('hidden'), 1400);
  }

  showHUD() {
    clearTimeout(this._hideHudTimer);
    this.bodyClass('playing', true);
    const hud = $('#hud');
    hud.classList.remove('hidden');
    void hud.offsetWidth;
    hud.classList.add('is-live');
  }

  hideHUD() {
    this.bodyClass('playing', false);
    $('#hud').classList.remove('is-live');
    clearTimeout(this._hideHudTimer);
    this._hideHudTimer = setTimeout(() => $('#hud').classList.add('hidden'), 400);
  }

  setPlanetTheme(def) {
    if (!def) return;
    this.currentPlanetId = def.id;
    const p = def.palette;
    const root = document.documentElement;
    const accent = p.uiAccent || p.accentCss;
    const warm = p.uiWarm || p.accentCss;
    root.style.setProperty('--accent', accent);
    root.style.setProperty('--accent-strong', accent);
    root.style.setProperty('--warm', warm);
    const rgb = this.hexToRgb(accent);
    const warmRgb = this.hexToRgb(warm);
    if (rgb) root.style.setProperty('--accent-rgb', `${rgb.r}, ${rgb.g}, ${rgb.b}`);
    if (warmRgb) root.style.setProperty('--warm-rgb', `${warmRgb.r}, ${warmRgb.g}, ${warmRgb.b}`);
    $('#hud-planet-code').textContent = def.code;
    $('#hud-planet-zh').textContent = def.nameZh;
    $('#hud-planet-en').textContent = def.nameEn;
    $('#hud-biome').textContent = def.biome;
    $('#hud-gravity').textContent = `${(def.gravity / 9.8).toFixed(2)} G`;
    $('#hud-temp').textContent = def.temperature;
    $('#pause-location').textContent = `${def.code} ${def.nameZh} · ${(def.gravity / 9.8).toFixed(2)} G`;
  }

  hexToRgb(hex) {
    if (!hex) return null;
    const h = hex.replace('#', '');
    const n = parseInt(h.length === 3 ? h.split('').map((c) => c + c).join('') : h, 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  }

  setResources(inv) {
    this.updateResources(inv);
  }

  updateResources(inv) {
    for (const key of ['alloy', 'fiber', 'crystal', 'stardust']) {
      const el = $(`#res-${key}`);
      if (!el) continue;
      const v = inv[key] || 0;
      if (el.textContent !== String(v)) {
        el.textContent = v;
        const item = el.closest('.resource-item');
        item?.classList.remove('bump');
        void item?.offsetWidth;
        item?.classList.add('bump');
      }
    }
    const credits = inv.credits || 0;
    const hudCredits = $('#hud-credits');
    if (hudCredits) hudCredits.textContent = credits;
    if (this.merchantOpen) this.updateMerchant(inv);
  }

  openMerchant() {
    if (!this.game) return;
    this.merchantOpen = true;
    this.renderMerchant(this.game.inventory || {});
    this.bodyClass('merchant-open', true);
    $('#merchant').classList.remove('hidden');
    this.game.audio?.ui?.();
  }

  closeMerchant() {
    this.merchantOpen = false;
    this.bodyClass('merchant-open', false);
    $('#merchant').classList.add('hidden');
  }

  updateMerchant(inv) {
    if (!this.merchantOpen) return;
    this.renderMerchant(inv || {});
  }

  renderMerchant(inv) {
    const credits = inv.credits || 0;
    const creditEl = $('#merchant-credits');
    if (creditEl) creditEl.textContent = credits;

    const sell = $('#merchant-sell-list');
    if (sell) {
      sell.innerHTML = Object.entries(MERCHANT_PRICES).map(([key, price]) => {
        const info = RESOURCE_INFO[key];
        const count = inv[key] || 0;
        return `<div class="merchant-item ${count ? '' : 'is-empty'}">
          <span class="mi-glyph" style="color:${info.color}">${info.icon}</span>
          <span class="mi-main"><b>${info.zh}</b><small>${info.en} · 持有 ${count}</small></span>
          <span class="mi-price">+${price} <small>星币</small></span>
          <button class="merchant-btn" data-sell="${key}" ${count ? '' : 'disabled'}>出售</button>
        </div>`;
      }).join('');
    }

    const buy = $('#merchant-buy-list');
    if (buy) {
      buy.innerHTML = MERCHANT_STOCK.map((item) => `<div class="merchant-item supply-item">
        <span class="mi-glyph">${item.icon}</span>
        <span class="mi-main"><b>${item.nameZh}</b><small>${item.description}</small></span>
        <span class="mi-price">${item.price} <small>星币</small></span>
        <button class="merchant-btn buy" data-buy="${item.id}" ${credits >= item.price ? '' : 'disabled'}>购买</button>
      </div>`).join('');
    }
  }

  updateVitals(health, shield = 100) {
    health = clamp(health, 0, 100);
    shield = clamp(shield, 0, 100);
    $('#health-bar').style.width = `${health}%`;
    $('#shield-bar').style.width = `${shield}%`;
    $('#health-num').textContent = Math.round(health);
    $('#shield-num').textContent = Math.round(shield);
  }

  updateAmmo(ammo, reserve, reloading, magSize = 12) {
    if (this.cache.ammo !== ammo) {
      $('#ammo-count').textContent = ammo;
      this.cache.ammo = ammo;
    }
    if (this.cache.reserve !== reserve) {
      $('#ammo-reserve').textContent = reserve;
      this.cache.reserve = reserve;
    }
    $('#reload-label').textContent = reloading ? 'RELOADING…' : '';
    const pips = $('#ammo-pips');
    if (this.cache.pips !== `${ammo}/${magSize}`) {
      pips.innerHTML = Array.from({ length: magSize }, (_, i) => `<i class="${i >= ammo ? 'spent' : ''}"></i>`).join('');
      this.cache.pips = `${ammo}/${magSize}`;
    }
  }

  setObjective(title, sub = '', progress = 0, count = '') {
    const key = `${title}|${sub}|${progress}|${count}`;
    if (this.objectiveKey === key) return;
    this.objectiveKey = key;
    $('#objective-text').textContent = title;
    $('#objective-sub').textContent = sub;
    $('#objective-progress').style.width = `${clamp(progress, 0, 1) * 100}%`;
    $('#objective-count').textContent = count;
  }

  setMode(mode) {
    this.mode = mode;
    this.bodyClass('mode-space', mode === 'space');
    const spaceHud = $('#space-hud');
    if (mode === 'space') {
      spaceHud.classList.remove('hidden');
      $('#weapon-panel').style.opacity = '0';
      $('.vitals-panel').style.opacity = '0';
    } else {
      spaceHud.classList.add('hidden');
      $('#weapon-panel').style.opacity = '';
      $('.vitals-panel').style.opacity = '';
    }
    $('#mode-label').textContent = mode === 'space' ? 'CRUISE / 深空航行' : 'SURFACE / 地表探索';
    const interactBtn = $('#touch-interact');
    if (interactBtn) {
      if (mode === 'space') {
        interactBtn.dataset.touch = 'KeyF';
        interactBtn.innerHTML = '降<small>LAND</small>';
      } else {
        interactBtn.dataset.touch = 'KeyE';
        interactBtn.innerHTML = 'E<small>互动</small>';
      }
    }
    const stickLabel = $('#stick-label');
    if (stickLabel) stickLabel.textContent = mode === 'space' ? 'PUSH' : 'MOVE';
    this.setBuildMode(false);
    this.setContext('', 'F', false);
  }

  setSpaceLabels() {
    $('#hud-planet-code').textContent = 'SW-01';
    $('#hud-planet-zh').textContent = '织星者号';
    $('#hud-planet-en').textContent = 'STARWEAVER';
    $('#hud-biome').textContent = '深空航行';
    $('#hud-gravity').textContent = '0.00 G';
    $('#hud-temp').textContent = '−270°C';
    const help = $('#space-hud .flight-help span:last-child');
    if (help) help.innerHTML = '<kbd>F</kbd> 着陆';
    this.setMode('space');
  }

  setBlackHoleLabels() {
    $('#hud-planet-code').textContent = 'BH-01';
    $('#hud-planet-zh').textContent = '事件视界';
    $('#hud-planet-en').textContent = 'EVENT HORIZON';
    $('#hud-biome').textContent = '超巨质量引力井';
    $('#hud-gravity').textContent = '∞';
    $('#hud-temp').textContent = '0 K';
    const help = $('#space-hud .flight-help span:last-child');
    if (help) help.innerHTML = '<kbd>F</kbd> 返航';
    this.setMode('space');
  }

  updatePower(power) {
    const el = $('#hud-power');
    if (!el) return;
    const txt = power > 0 ? `+${power}` : `${power}`;
    if (el.textContent !== txt) {
      el.textContent = txt;
      el.style.color = power >= 0 ? 'var(--accent)' : 'var(--danger)';
    }
  }

  updateSpeciesCount(count) {
    const el = $('#hud-species');
    if (!el) return;
    const txt = `${count} SPECIES`;
    if (el.textContent !== txt) el.textContent = txt;
  }

  setLockPrompt(on) {
    const el = $('#lock-prompt');
    if (el) el.classList.toggle('visible', !!on);
  }

  setAiming(v) {
    this.bodyClass('aiming', v);
  }

  setInteraction({ visible = false, key = 'E', text = '', sub = '', progress = null, hold = false }) {
    const el = $('#interaction-hint');
    if (!visible) {
      el.classList.remove('visible');
      return;
    }
    el.classList.add('visible');
    $('#interact-key').textContent = key;
    $('#interact-text').textContent = text;
    $('#interact-sub').textContent = sub;
    const ring = $('#hold-ring');
    if (hold) {
      ring.classList.add('visible');
      $('#hold-progress').style.strokeDashoffset = String(100 - clamp(progress || 0, 0, 1) * 100);
    } else {
      ring.classList.remove('visible');
    }
  }

  setContext(text, key = 'E', visible = true) {
    const el = $('#interact-context');
    el.classList.toggle('visible', visible);
    if (visible) {
      $('#context-key').textContent = key;
      $('#context-copy').textContent = text;
    }
  }

  setReticleLabel(text, visible = true) {
    const el = $('#reticle-label');
    el.textContent = visible ? text : '';
    el.style.opacity = visible ? 1 : 0;
  }

  markHit() {
    const el = $('#hit-marker');
    el.classList.remove('flash');
    void el.offsetWidth;
    el.classList.add('flash');
  }

  flashDamage() {
    const now = performance.now();
    if (now - (this._lastDamageFlash || 0) < 180) return;
    this._lastDamageFlash = now;
    const el = $('#damage-flash');
    el.classList.add('active');
    clearTimeout(this._damageFlashTimer);
    this._damageFlashTimer = setTimeout(() => el.classList.remove('active'), 180);
  }

  showNotification(text, type = 'info', duration = 3400) {
    const stack = $('#notification-stack');
    const el = document.createElement('div');
    el.className = 'notification';
    const icons = { info: '◇', success: '✦', warn: '△', resource: '◆' };
    const split = text.split('|');
    el.innerHTML = `<span class="n-ico">${icons[type] || '◇'}</span><span>${split[0]}${split[1] ? ` <strong>${split[1]}</strong>` : ''}</span>`;
    stack.appendChild(el);
    while (stack.children.length > 3) stack.firstElementChild.remove();
    setTimeout(() => {
      el.classList.add('out');
      setTimeout(() => el.remove(), 500);
    }, duration);
  }

  showToast(text, duration = 2200) {
    const stack = $('#toast-stack');
    const el = document.createElement('div');
    el.className = 'toast';
    el.textContent = text;
    stack.appendChild(el);
    while (stack.children.length > 2) stack.firstElementChild.remove();
    setTimeout(() => {
      el.classList.add('fade');
      setTimeout(() => el.remove(), 750);
    }, duration);
  }

  showScan(species) {
    if (!species) return;
    $('#scan-name').textContent = species.nameZh;
    $('#scan-en').textContent = species.nameEn;
    $('#scan-temper').textContent = species.temperament;
    $('#scan-desc').textContent = species.description;
    $('#scan-code').textContent = `SPECIMEN ${species.planet?.[0]?.toUpperCase() || 'X'}-${String(Math.floor(Math.random() * 899) + 100)}`;
    $('#scan-card').classList.remove('hidden');
    this.game?.audio?.discovery?.();
  }

  hideScan() {
    $('#scan-card').classList.add('hidden');
  }

  setCinematic(on, label = '') {
    if (this.settings.cine) $('#cinema-bars').classList.toggle('active', on);
    if (label) $('#cinema-label').textContent = label;
    this.bodyClass('cinematic', on);
  }

  showLocationCard(def, duration = 4800) {
    const el = $('#cinematic-title');
    $('#cine-kicker').textContent = `ARRIVAL / ${def.code}`;
    $('#cine-name').textContent = def.nameZh;
    $('#cine-en').textContent = def.nameEn;
    $('#cine-sub').textContent = def.tagline;
    el.classList.add('visible');
    clearTimeout(this._locationTimer);
    this._locationTimer = setTimeout(() => el.classList.remove('visible'), duration);
  }

  hideLocationCard() {
    $('#cinematic-title').classList.remove('visible');
  }

  clearTransientUI() {
    this.hideLocationCard();
    this.updateMarkers([]);
    const notes = $('#notification-stack');
    const toasts = $('#toast-stack');
    if (notes) notes.innerHTML = '';
    if (toasts) toasts.innerHTML = '';
  }

  setBuildMode(on) {
    this.bodyClass('build-mode', on);
    $('#build-bar').classList.toggle('hidden', !on);
    $('#btn-build').classList.toggle('on', on);
    if (!on) this.activeBuildId = null;
  }

  buildBuildBar() {
    const container = $('#build-items');
    container.innerHTML = BUILD_DEFS.map((def, i) => `
      <button class="build-item" data-build="${def.id}">
        <span class="bi-key">${i + 1}</span>
        <span class="bi-icon">${def.icon}</span>
        <span class="bi-copy"><b>${def.nameZh}</b><small>${def.nameEn}</small></span>
      </button>
    `).join('');
    this.buildItems = [...container.querySelectorAll('.build-item')];
  }

  selectBuildDef(id) {
    this.activeBuildId = id;
    this.buildItems.forEach((el) => el.classList.toggle('selected', el.dataset.build === id));
    const def = BUILD_DEFS.find((d) => d.id === id);
    if (def) {
      const cost = Object.entries(def.cost).map(([k, v]) => `${RESOURCE_INFO[k]?.zh || k} ${v}`).join(' · ');
      $('#build-cost').textContent = cost;
    } else {
      $('#build-cost').textContent = '';
    }
  }

  updateBuildValidity(valid, reason = '') {
    const el = $('#build-valid');
    el.textContent = valid ? '定位有效 / READY' : (reason || '无法在此建造');
    el.classList.toggle('invalid', !valid);
  }

  setOverlayOpen(on) {
    this.overlayLock = on;
    this.game?.setOverlay?.(on);
  }

  openStarmap() {
    if (!this.game?.canOpenMap?.()) {
      this.showToast(this.mode === 'surface' ? '星图只在深空航行时可用' : '当前无法打开星图');
      return;
    }
    this.mapOpen = true;
    $('#starmap').classList.remove('hidden');
    this.setOverlayOpen(true);
    const data = this.game.getMapData?.() || {};
    const start = data.targetId || data.currentPlanetId || 'verdant';
    this.mapPlanetId = start;
    this.updateMapDistances(data.distances || {});
    try {
      this.updateMapPlanet(start);
    } catch (err) {
      console.warn('[starmap] 面板刷新失败，星图仍会绘制：', err);
    }
    this.startStarmapLoop();
    this.game.audio?.ui?.();
  }

  startStarmapLoop() {
    this.stopStarmapLoop();
    this._mapLast = performance.now();
    const tick = () => {
      if (!this.mapOpen) return;
      // 星图打开时游戏是暂停的，这里手动推进公转，保证图上位置是真·实时演算。
      const now = performance.now();
      const dt = Math.min(0.06, Math.max(0, (now - this._mapLast) / 1000));
      this._mapLast = now;
      this.game?.updateSolarOrbits?.(dt);
      this.drawStarmap();
      const sel = this.game?.planets?.find((x) => x.def.id === this.mapPlanetId);
      if (sel && this.game?.rocket?.root) {
        const d = this.game.rocket.root.position.distanceTo(sel.center);
        const el = $('#map-distance');
        if (el) el.textContent = formatDistance(Math.max(0, d - sel.radius));
      }
      this._mapRAF = requestAnimationFrame(tick);
    };
    this._mapRAF = requestAnimationFrame(tick);
  }

  stopStarmapLoop() {
    if (this._mapRAF) cancelAnimationFrame(this._mapRAF);
    this._mapRAF = 0;
  }

  /** 实时星图：直接读场景里星球的当前公转位置，不用贴图、不用固定坐标。 */
  drawStarmap() {
    const g = this.game;
    const cv = $('#starmap-canvas');
    if (!g || !cv) return;
    const rect = cv.getBoundingClientRect();
    const W = rect.width || 640;
    const H = rect.height || 480;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    if (cv.width !== Math.round(W * dpr) || cv.height !== Math.round(H * dpr)) {
      cv.width = Math.round(W * dpr);
      cv.height = Math.round(H * dpr);
    }
    const ctx = cv.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);

    const planets = g.planets || [];
    if (!planets.length) return;
    const maxR = Math.max(...planets.map((p) => (p.def && p.def.orbit ? p.def.orbit.radius : 0)), 1200) * 1.16;
    const cx = W / 2;
    const cy = H / 2;
    const scale = (Math.min(W, H) * 0.46) / maxR;
    const TILT = 0.66;
    const LIFT = 0.44;
    const proj = (x, y, z) => [cx + x * scale, cy + (z * TILT - y * LIFT) * scale];

    ctx.save();
    ctx.strokeStyle = 'rgba(190, 220, 225, 0.05)';
    ctx.lineWidth = 1;
    for (let ring = 1; ring <= 4; ring++) {
      const rr = ((maxR * ring) / 4) * scale;
      ctx.beginPath();
      ctx.ellipse(cx, cy, rr, rr * TILT, 0, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();

    for (const p of planets) {
      const orbit = p.def && p.def.orbit;
      if (!orbit || !g.getOrbitPoint) continue;
      const accent = (p.def && p.def.palette && p.def.palette.accentCss) || '#9fd6c8';
      const active = this.mapPlanetId === p.def.id;
      ctx.save();
      ctx.strokeStyle = accent;
      ctx.globalAlpha = active ? 0.42 : 0.18;
      ctx.lineWidth = active ? 1.4 : 1;
      ctx.beginPath();
      const steps = 160;
      for (let i = 0; i <= steps; i++) {
        const pt = g.getOrbitPoint(orbit, (i / steps) * Math.PI * 2);
        const xy = proj(pt.x, pt.y, pt.z);
        if (i === 0) ctx.moveTo(xy[0], xy[1]);
        else ctx.lineTo(xy[0], xy[1]);
      }
      ctx.stroke();
      ctx.restore();
    }

    const sun = proj(0, 0, 0);
    const sunGrad = ctx.createRadialGradient(sun[0], sun[1], 0, sun[0], sun[1], 46);
    sunGrad.addColorStop(0, 'rgba(255, 244, 208, 0.95)');
    sunGrad.addColorStop(0.22, 'rgba(255, 206, 130, 0.5)');
    sunGrad.addColorStop(1, 'rgba(255, 180, 90, 0)');
    ctx.fillStyle = sunGrad;
    ctx.beginPath();
    ctx.arc(sun[0], sun[1], 46, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255, 246, 220, 1)';
    ctx.beginPath();
    ctx.arc(sun[0], sun[1], 9, 0, Math.PI * 2);
    ctx.fill();
    ctx.font = '600 9px ui-monospace, monospace';
    ctx.fillStyle = 'rgba(255, 236, 200, 0.5)';
    ctx.fillText('SOL / 太阳', sun[0] + 16, sun[1] + 3);

    for (const p of planets) {
      const accent = (p.def && p.def.palette && p.def.palette.accentCss) || '#9fd6c8';
      const xy = proj(p.center.x, p.center.y, p.center.z);
      const base = 4 + Math.sqrt((p.def && p.def.radius) || 60) * 0.72;
      const active = this.mapPlanetId === p.def.id;
      const glow = ctx.createRadialGradient(xy[0], xy[1], 0, xy[0], xy[1], base * 3.2);
      glow.addColorStop(0, accent);
      glow.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.save();
      ctx.globalAlpha = active ? 0.55 : 0.3;
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(xy[0], xy[1], base * 3.2, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      ctx.fillStyle = accent;
      ctx.beginPath();
      ctx.arc(xy[0], xy[1], base, 0, Math.PI * 2);
      ctx.fill();
      if (active) {
        ctx.strokeStyle = 'rgba(255,255,255,0.75)';
        ctx.lineWidth = 1.2;
        ctx.beginPath();
        ctx.arc(xy[0], xy[1], base + 7, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.font = '600 12px system-ui, sans-serif';
      ctx.fillStyle = active ? 'rgba(255,255,255,0.95)' : 'rgba(235,240,240,0.6)';
      ctx.fillText(p.def.nameZh || '', xy[0] + base + 10, xy[1] - 1);
      ctx.font = '500 8px ui-monospace, monospace';
      ctx.fillStyle = 'rgba(200,215,215,0.4)';
      ctx.fillText(`${p.def.nameEn || ''} / ${p.def.code || ''}`, xy[0] + base + 10, xy[1] + 11);
      p._mapX = xy[0];
      p._mapY = xy[1];
    }

    const ship = g.rocket && g.rocket.root ? g.rocket.root.position : null;
    if (ship) {
      const xy = proj(ship.x, ship.y, ship.z);
      ctx.save();
      ctx.translate(xy[0], xy[1]);
      ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
      ctx.beginPath();
      ctx.moveTo(0, -7);
      ctx.lineTo(4.6, 5);
      ctx.lineTo(0, 2.4);
      ctx.lineTo(-4.6, 5);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
      ctx.font = '500 8px ui-monospace, monospace';
      ctx.fillStyle = 'rgba(255,255,255,0.5)';
      ctx.fillText('SW-01', xy[0] + 9, xy[1] + 3);
    }
  }

  pickMapPlanet(ev) {
    const cv = $('#starmap-canvas');
    const g = this.game;
    if (!cv || !g) return;
    const r = cv.getBoundingClientRect();
    const mx = ev.clientX - r.left;
    const my = ev.clientY - r.top;
    let best = null;
    let bestD = 48;
    for (const p of g.planets || []) {
      if (p._mapX == null) continue;
      const d = Math.hypot(p._mapX - mx, p._mapY - my);
      if (d < bestD) { bestD = d; best = p; }
    }
    if (best) {
      this.updateMapPlanet(best.def.id);
      this.game.audio?.ui?.();
    }
  }

  closeStarmap() {
    if (!this.mapOpen) return;
    this.mapOpen = false;
    this.stopStarmapLoop();
    $('#starmap').classList.add('hidden');
    this.setOverlayOpen(false);
    this.game.audio?.ui?.();
  }

  updateMapDistances(distances) {
    this.mapDistances = distances;
    for (const [id, d] of Object.entries(distances)) {
      const btn = $(`#orbital-map .p-${id}`);
      if (!btn) continue;
      let sub = btn.querySelector('.mp-dist');
      if (!sub) {
        sub = document.createElement('span');
        sub.className = 'mp-dist';
        sub.style.cssText = 'position:absolute;left:78px;top:calc(50% + 21px);font-size:5px;letter-spacing:.1em;color:rgba(255,255,255,.25);';
        btn.appendChild(sub);
      }
      sub.textContent = d == null ? '' : formatDistance(d);
    }
  }

  updateMapPlanet(id) {
    const planet = this.game.planets?.find((p) => p.def.id === id);
    if (!planet) return;
    const def = planet.def;
    this.mapPlanetId = id;
    $$('#orbital-map .map-planet').forEach((p) => p.classList.toggle('active', p.dataset.planet === id));
    $('#map-planet-zh').textContent = def.nameZh;
    $('#map-planet-en').textContent = `${def.nameEn} / ${def.code}`;
    $('#map-description').textContent = def.intro.replace(/\n/g, ' ');
    $('#map-radius').textContent = `${Math.round(def.radius * 10)} km`;
    $('#map-gravity').textContent = `${(def.gravity / 9.8).toFixed(2)} G`;
    $('#map-biome').textContent = def.biome;
    $('#map-resource').textContent = def.resource;
    const d = this.mapDistances?.[id];
    $('#map-distance').textContent = d == null ? '当前位置' : formatDistance(d);
    const isCurrent = this.game.currentPlanet?.def.id === id;
    const ground = this.game.mode === 'surface';
    this.updateMapCourseButton(isCurrent || ground);
    const mapNote = $('#map-note');
    if (mapNote) mapNote.textContent = isCurrent
      ? '你当前正位于这颗星球。'
      : ground
        ? '需要先返回织星者号，进入深空后才能设定新航向。'
        : '设定航向后，返回驾驶舱继续航行。';
  }

  updateMapCourseButton(disabled) {
    const btn = $('#map-set-course');
    if (!btn) return;
    btn.style.opacity = disabled ? '.4' : '1';
    btn.style.pointerEvents = disabled ? 'none' : 'auto';
  }

  openPause() {
    if (this.pauseOpen || this.mapOpen || this.settingsOpen) return;
    if (!this.game?.isPlayingState?.()) return;
    this.pauseOpen = true;
    $('#pause').classList.remove('hidden');
    this.game.pause?.();
    this.setOverlayOpen(true);
    this.game.audio?.ui?.();
  }

  closePause(resume = true) {
    if (!this.pauseOpen) return;
    this.pauseOpen = false;
    $('#pause').classList.add('hidden');
    this.setOverlayOpen(false);
    if (resume) this.game.resume?.();
    this.game.audio?.ui?.();
  }

  openSettings(from = 'menu') {
    this.settingsReturn = from;
    this.settingsOpen = true;
    this.applySettingsToDOM();
    if (from === 'pause') $('#pause').classList.add('hidden');
    $('#settings').classList.remove('hidden');
    this.setOverlayOpen(true);
    this.game.audio?.ui?.();
  }

  closeSettings() {
    if (!this.settingsOpen) return;
    this.settingsOpen = false;
    $('#settings').classList.add('hidden');
    if (this.settingsReturn === 'pause' && this.pauseOpen) {
      $('#pause').classList.remove('hidden');
      this.setOverlayOpen(true);
    } else {
      this.setOverlayOpen(false);
      if (this.settingsReturn === 'pause') this.closePause(true);
    }
    this.game.audio?.ui?.();
  }

  showDeath() {
    $('#death').classList.remove('hidden');
    this.setOverlayOpen(true);
    this.game.audio?.ui?.();
  }

  hideDeath() {
    $('#death').classList.add('hidden');
    this.setOverlayOpen(false);
  }

  showGravityWarning(opts = null) {
    const el = $('#gravity-warning');
    if (!el) return;
    if (opts) {
      const kicker = el.querySelector('.eyebrow');
      const title = el.querySelector('strong');
      const sub = el.querySelector('small');
      if (kicker && opts.kicker) kicker.textContent = opts.kicker;
      if (title && opts.title) title.textContent = opts.title;
      if (sub && opts.sub) sub.textContent = opts.sub;
    }
    el.classList.remove('hidden');
    requestAnimationFrame(() => el.classList.add('visible'));
  }

  hideGravityWarning() {
    const el = $('#gravity-warning');
    if (!el) return;
    el.classList.remove('visible');
    el.classList.add('hidden');
  }

  // ── 流金之冕：风暴 HUD 与迷失结算 ──────────────────────────
  showStormHUD() {
    const el = $('#storm-hud');
    if (!el) return;
    el.classList.remove('hidden');
    requestAnimationFrame(() => el.classList.add('visible'));
  }

  hideStormHUD() {
    const el = $('#storm-hud');
    if (!el) return;
    el.classList.remove('visible');
    el.classList.add('hidden');
  }

  // 死亡字卡：无论如何 8 秒后自动回主菜单（按钮/点击/按键都失效也能出去）
  _armDeathAutoReturn() {
    clearTimeout(this._deathReturnTimer);
    this._cardShownAt = performance.now();
    this._deathReturnTimer = setTimeout(() => {
      console.warn('[ui] 死亡字卡自动返回主菜单');
      this._bailToMenu?.();
    }, 8000);
  }

  _clearDeathAutoReturn() {
    clearTimeout(this._deathReturnTimer);
    this._deathReturnTimer = null;
  }

  showStormDeath() {
    const el = $('#storm-death');
    if (!el) return;
    document.exitPointerLock?.();
    this._cardGuardUntil = performance.now() + 400;
    this.setBlackHoleDeathFade(false);
    el.classList.remove('hidden');
    requestAnimationFrame(() => el.classList.add('visible'));
    this.setOverlayOpen(true);
    this._armDeathAutoReturn();
    this.game?.audio?.damage?.();
  }

  hideStormDeath() {
    const el = $('#storm-death');
    if (!el) return;
    el.classList.add('hidden');
    el.classList.remove('visible');
    this.setBlackHoleDeathFade(false);
    this.setOverlayOpen(false);
  }

  setBlackHoleDeathFade(on) {
    $('#blackhole-death-fade')?.classList.toggle('active', !!on);
  }

  showSunDeath() {
    const el = $('#sun-death');
    if (!el) return;
    document.exitPointerLock?.();
    this._cardGuardUntil = performance.now() + 400;
    el.classList.remove('hidden');
    requestAnimationFrame(() => el.classList.add('visible'));
    this.setOverlayOpen(true);
    this._armDeathAutoReturn();
    this.game?.audio?.damage?.();
  }

  hideSunDeath() {
    this._clearDeathAutoReturn();
    const el = $('#sun-death');
    if (el) {
      el.classList.add('hidden');
      el.classList.remove('visible');
    }
    this.setBlackHoleDeathFade(false);
    this.setOverlayOpen(false);
  }

  showStationCrash() {
    const el = $('#station-crash');
    if (!el) return;
    document.exitPointerLock?.();
    this._cardGuardUntil = performance.now() + 400;
    el.classList.remove('hidden');
    requestAnimationFrame(() => el.classList.add('visible'));
    this.setOverlayOpen(true);
    this._armDeathAutoReturn();
    this.game?.audio?.damage?.();
  }

  hideStationCrash() {
    this._clearDeathAutoReturn();
    const el = $('#station-crash');
    if (el) {
      el.classList.add('hidden');
      el.classList.remove('visible');
    }
    this.setBlackHoleDeathFade(false);
    this.setOverlayOpen(false);
  }

  showStormLoading() {
    const el = $('#storm-loading');
    if (!el) return;
    el.classList.remove('hidden');
    this.setStormLoadingProgress(0);
  }

  setStormLoadingProgress(p) {
    const fill = $('#storm-loading-fill');
    const pct = $('#storm-loading-pct');
    const v = Math.max(0, Math.min(1, p || 0));
    if (fill) fill.style.width = `${(v * 100).toFixed(1)}%`;
    if (pct) pct.textContent = `${Math.round(v * 100)}%`;
  }

  hideStormLoading() {
    const el = $('#storm-loading');
    if (!el) return;
    el.classList.add('hidden');
  }

  showStationLocked() {
    const el = $('#station-locked');
    if (!el) return;
    this._cardGuardUntil = performance.now() + 400;
    el.classList.remove('hidden');
    requestAnimationFrame(() => el.classList.add('visible'));
    this.setOverlayOpen(true);
    this.game?.audio?.ui?.();
  }

  hideStationLocked() {
    const el = $('#station-locked');
    if (el) {
      el.classList.add('hidden');
      el.classList.remove('visible');
    }
    this.setOverlayOpen(false);
  }

  showBlackHoleDeath() {
    const el = $('#blackhole-death');
    if (!el) return;
    document.exitPointerLock?.();
    this._cardGuardUntil = performance.now() + 400;
    el.classList.remove('hidden');
    requestAnimationFrame(() => el.classList.add('visible'));
    this.setOverlayOpen(true);
    this._armDeathAutoReturn();
    this.game.audio?.damage?.();
  }

  hideBlackHoleDeath() {
    this._clearDeathAutoReturn();
    const el = $('#blackhole-death');
    if (el) {
      el.classList.add('hidden');
      el.classList.remove('visible');
    }
    this.setBlackHoleDeathFade(false);
    this.setOverlayOpen(false);
  }

  startFlightHUD(target) {
    this.setMode('space');
    this.flightTarget = target;
  }

  updateFlightHUD({ throttle, speed, target, targetId, distance, eta, distanceLabel, etaLabel, progress }) {
    const pct = clamp(throttle, 0, 1) * 100;
    $('#throttle-fill').style.width = `${pct}%`;
    $('#throttle-label').textContent = `THROTTLE ${Math.round(pct)}%`;
    $('#speed-value').textContent = Math.round(speed);
    if (target) {
      $('#target-name').textContent = target.nameZh;
      $('#flight-target .target-label').textContent = `目标航向 / ${target.nameEn || 'COURSE'}`;
    } else {
      $('#target-name').textContent = '自由航行';
    }
    if (distance != null || distanceLabel != null) {
      $('#target-distance').textContent = distanceLabel ?? formatDistance(distance);
      $('#target-eta').textContent = etaLabel ?? (eta != null ? `ETA ${this.formatEta(eta)}` : '—');
      let p = progress;
      if (p == null) {
        const total = this.mapDistances?.[targetId] || 1600;
        p = 1 - clamp(distance / total, 0, 1);
      }
      $('#target-line-fill').style.width = `${clamp(p, 0, 1) * 100}%`;
    } else {
      $('#target-distance').textContent = '—';
      $('#target-eta').textContent = '—';
    }
  }

  formatEta(seconds) {
    if (!Number.isFinite(seconds) || seconds > 999) return '—';
    const m = Math.floor(seconds / 60);
    const s = Math.round(seconds % 60);
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  }

  updateMarkers(items) {
    const layer = $('#world-markers');
    if (!layer) return;
    const alive = new Set();
    for (const item of items) {
      alive.add(item.id);
      const sig = `${item.type || ''}|${item.label || ''}|${item.sub || ''}`;
      let el = this.markers.get(item.id);
      if (!el) {
        el = document.createElement('div');
        el.className = `world-marker ${item.type || ''}`;
        el.innerHTML = `<span class="wm-ring"></span><span class="wm-label">${item.label || ''}</span><small class="wm-sub">${item.sub || ''}</small>`;
        el.dataset.sig = sig;
        layer.appendChild(el);
        this.markers.set(item.id, el);
      } else if (el.dataset.sig !== sig) {
        // 先隐藏时创建的元素只有空标签，重新出现必须重写内容，否则永远是空名字。
        el.className = `world-marker ${item.type || ''}`;
        el.innerHTML = `<span class="wm-ring"></span><span class="wm-label">${item.label || ''}</span><small class="wm-sub">${item.sub || ''}</small>`;
        el.dataset.sig = sig;
      }
      if (!item.visible) {
        el.classList.remove('visible');
        continue;
      }
      if (!el.classList.contains('visible')) el.classList.add('visible');
      const tf = `translate(${Math.round(item.x * 2) / 2}px, ${Math.round(item.y * 2) / 2}px) translate(-50%, -50%)`;
      if (el._tf !== tf) { el._tf = tf; el.style.transform = tf; }
      if (el.style.left !== '0px') { el.style.left = '0px'; el.style.top = '0px'; }
      if (item.opacity != null) {
        const op = String(Math.round(item.opacity * 20) / 20);
        if (el._op !== op) { el._op = op; el.style.opacity = op; }
      }
    }
    for (const [id, el] of this.markers) {
      if (!alive.has(id)) {
        el.remove();
        this.markers.delete(id);
      }
    }
  }

  updateHealthDanger(health) {
    this.bodyClass('low-health', health < 28);
  }

  planetName(id) {
    const def = this.game?.planets?.find((p) => p.def.id === id)?.def;
    return def ? def.nameZh : id;
  }

  resetHUDForSurface() {
    this.hideScan();
    this.setMode('surface');
    this.setAiming(false);
    this.setInteraction({ visible: false });
    this.setContext('', 'E', false);
    this.setBuildMode(false);
    this.bodyClass('low-health', false);
  }

  showCinematicTitle(kicker, name, en, sub, duration = 4200) {
    $('#cine-kicker').textContent = kicker;
    $('#cine-name').textContent = name;
    $('#cine-en').textContent = en;
    $('#cine-sub').textContent = sub;
    const el = $('#cinematic-title');
    el.classList.add('visible');
    clearTimeout(this._locationTimer);
    this._locationTimer = setTimeout(() => el.classList.remove('visible'), duration);
  }
}

