class ArrivalLoader {
  constructor() {
    this.el = document.getElementById('arrival-loader');
    this.canvas = document.getElementById('game-canvas');
    this.stage = document.getElementById('al-stage');
    this.code = document.getElementById('al-code');
    this.footCode = document.getElementById('al-foot-code');
    this.status = document.getElementById('al-status');
    this.statusCn = document.getElementById('al-status-cn');
    this.fill = document.getElementById('al-progress-fill');
    this.percent = document.getElementById('al-percent');
    this.pageCount = document.getElementById('al-page-count');
    this.pages = [];
    this.pageIndex = -1;
    this.progress = 0;
    this.hideTimer = null;
    this.planetId = null;
  }

  show(planet) {
    if (!this.el || !this.stage || !planet) return;
    const def = planet.def;
    this.planetId = def.id;
    const accent = def.palette?.uiAccent || '#a9e5cb';
    const warm = def.palette?.uiWarm || '#e6c699';
    const deep = def.palette?.deep || '#07100f';
    const ground = cssHex(def.terrain?.highland ?? def.palette?.ground, '#365140');
    this.el.style.setProperty('--al-accent', accent);
    this.el.style.setProperty('--al-accent-rgb', rgbTuple(accent));
    this.el.style.setProperty('--al-warm', warm);
    this.el.style.setProperty('--al-warm-rgb', rgbTuple(warm));
    this.el.style.setProperty('--al-deep', deep);
    this.el.style.setProperty('--al-ground', ground);
    this.code.textContent = def.code;
    this.footCode.textContent = `${def.nameEn} / ${def.code}`;
    const introLines = (def.intro || '').split('\n').filter(Boolean);
    const intro = introLines[0] || def.tagline || '';
    this.stage.innerHTML = `
      <article class="al-page" data-page="0">
        <div class="al-copy">
          <div class="al-kicker"><b>01</b><i></i>SURFACE ASSET SYNC</div>
          <h2 class="al-title">${def.nameZh}</h2>
          <div class="al-title-en">${def.nameEn}</div>
          <p class="al-tagline">${def.tagline}</p>
          <p class="al-body">${intro}</p>
          <div class="al-specs">
            <div><span>BIOME / 地貌</span><b>${def.biome}</b></div>
            <div><span>ATMOSPHERE / 大气</span><b>${def.atmosphere}</b></div>
            <div><span>GRAVITY / 重力</span><b>${def.gravity.toFixed(1)} M/S²</b></div>
          </div>
        </div>
        ${orbitPlate(def, def.code)}
      </article>
      <article class="al-page" data-page="1">
        <div class="al-copy">
          <div class="al-kicker"><b>02</b><i></i>TERRAIN STREAM</div>
          <h2 class="al-title medium">着陆区测绘</h2>
          <div class="al-title-en">SITE SURVEY / ${def.code}</div>
          <p class="al-body">选定穹顶平坦、岩层稳定的东南坡面作为第一着陆区。地表信标正在同步下降走廊。</p>
          <div class="al-data-grid">
            <div><span>BIOME / 地貌</span><b>${def.biome}</b><small>SURFACE CLASS 04</small></div>
            <div><span>TEMPERATURE / 温度</span><b>${def.temperature}</b><small>MEAN AMBIENT</small></div>
            <div><span>ATMOSPHERE / 大气</span><b>${def.atmosphere}</b><small>EXTERNAL SUIT ONLY</small></div>
            <div><span>RESOURCE / 资源</span><b>${def.resource}</b><small>SPECTRAL SIGNATURE</small></div>
          </div>
        </div>
        ${surveyPlate()}
      </article>
      <article class="al-page" data-page="2">
        <div class="al-copy">
          <div class="al-kicker"><b>03</b><i></i>DESCENT PREP</div>
          <h2 class="al-title medium">最终进近</h2>
          <div class="al-title-en">FINAL APPROACH · ${def.nameEn}</div>
          <p class="al-body">反推引擎已接入手动权限。下降走廊净空，起落架展开，等待星面接触信号。</p>
          <div class="al-approach-readout"><span>DESCENT RATE / 下降率</span><b>2.4</b><small>M/S</small></div>
          <div class="al-signal-line"><i></i>TOUCHDOWN WINDOW CLEARED / 着陆窗口已确认</div>
        </div>
        ${landingPlate(def)}
      </article>`;
    this.pages = [...this.stage.querySelectorAll('.al-page')];
    this.pageIndex = -1;
    this.progress = 0;
    clearTimeout(this.hideTimer);
    this.el.classList.remove('hidden', 'is-leaving');
    this.el.setAttribute('aria-hidden', 'false');
    if (this.canvas) this.canvas.style.display = 'none';
    void this.el.offsetWidth;
    this.el.classList.add('is-visible');
    this.setProgress(0);
  }

  setProgress(value) {
    if (!this.el || !this.pages.length) return;
    const p = clamp(value, 0, 1);
    this.progress = p;
    const pct = Math.round(p * 100);
    if (this.fill) this.fill.style.width = `${pct}%`;
    if (this.percent) this.percent.textContent = `${String(pct).padStart(2, '0')}%`;
    const nextIndex = pct >= 100 ? 2 : pct < 34 ? 0 : pct < 68 ? 1 : 2;
    if (nextIndex !== this.pageIndex) {
      this.pageIndex = nextIndex;
      this.pages.forEach((page, i) => {
        const active = i === nextIndex;
        page.classList.toggle('active', active);
        page.setAttribute('aria-hidden', String(!active));
      });
      if (this.pageCount) this.pageCount.textContent = `0${nextIndex + 1} / 03`;
    }
    const line = pct >= 100 ? { en: 'SURFACE ASSETS READY', cn: '地表资源加载完成' } : STATUS[nextIndex];
    if (this.status) this.status.textContent = line.en;
    if (this.statusCn) this.statusCn.textContent = line.cn;
  }

  hide() {
    if (!this.el) return;
    this.el.classList.add('is-leaving');
    this.el.setAttribute('aria-hidden', 'true');
    if (this.canvas) this.canvas.style.display = '';
    clearTimeout(this.hideTimer);
    this.hideTimer = setTimeout(() => {
      this.el.classList.add('hidden');
      this.el.classList.remove('is-leaving', 'is-visible');
    }, 620);
  }
}

