      hasSolar: list.some((b) => b.type === 'solar'),
      hasResearch: list.some((b) => b.type === 'research'),
      hasStorage: list.some((b) => b.type === 'storage'),
      hasLamp: list.some((b) => b.type === 'lamp'),
