    // avoid placing too close to rocket, resources, landmarks, buildings
    let invalidReason = '';
    const rocketPos = this.game.rocket.root.position;
    if (position.distanceTo(rocketPos) < 5.5) invalidReason = '距离飞船太近';
    if (newDir.angleTo(planet.landmarkDir) < 0.085) invalidReason = '地标附近无法建造';
    for (const b of this.allForPlanet(planet)) {
      if (b.root.position.distanceTo(position) < 3.8) invalidReason = '与其他设施过近';
    }
