const Z = new Vector3(0, 0, 1);

class Combat {
  constructor(game) {
    this.game = game;
    this.scene = game.scene;
    this.projectiles = [];
    this.ammo = 12;
    this.magSize = 12;
    this.maxReserve = 48;
    this.reserve = this.maxReserve;
    this.reloading = false;
    this.reloadTime = 0;
    this.cooldown = 0;
    this.muzzleFlash = null;
    this.createMuzzleFlash();
  }

  createMuzzleFlash() {
    const mat = new SpriteMaterial({
      map: TEX.glow,
      color: 0xd4fff0,
      transparent: true,
      opacity: 0.9,
      blending: AdditiveBlending,
      depthWrite: false,
      depthTest: true,
      toneMapped: false,
    });
    const sprite = new Sprite(mat);
    sprite.scale.set(1.3, 1.3, 1);
    sprite.visible = false;
    this.scene.add(sprite);
    this.muzzleFlash = sprite;
    this.muzzleTime = 0;
  }

  reset() {
    this.ammo = this.magSize;
    this.reserve = this.maxReserve;
    this.reloading = false;
    this.reloadTime = 0;
  }

  refill() {
    this.ammo = this.magSize;
    this.reserve = this.maxReserve;
    this.reloading = false;
    this.reloadTime = 0;
  }

  tryReload() {
    if (this.reloading || this.ammo >= this.magSize || this.reserve <= 0) return false;
    this.reloading = true;
    this.reloadTime = 1.15;
    this.game.audio?.tone?.(220, 0.2, 0.03, 'square', 0.7, 0.1);
    return true;
  }

  tryFire() {
    const g = this.game;
    if (!g.stateAllowsCombat()) return false;
    if (this.reloading || this.cooldown > 0) return false;
    if (this.ammo <= 0) {
      this.tryReload();
      return false;
    }
    this.ammo--;
    this.cooldown = 0.19;
    const muzzle = g.player.getMuzzleWorld(new Vector3());
    const ray = g.getAimRay();
    const target = ray.origin.clone().addScaledVector(ray.direction, 55);
    const dir = target.sub(muzzle).normalize();
    // slight spread in aim mode
    if (!g.aiming) {
      dir.x += (Math.random() - 0.5) * 0.012;
      dir.y += (Math.random() - 0.5) * 0.012;
      dir.normalize();
    }
    this.spawnProjectile(muzzle, dir);
    g.player.triggerShoot();
    g.audio.shoot();
    g.cameraShake = Math.min(0.35, (g.cameraShake || 0) + 0.09);
    this.muzzleFlash.position.copy(muzzle);
    this.muzzleFlash.visible = true;
    this.muzzleTime = 0.075;
    this.muzzleFlash.material.rotation = Math.random() * Math.PI;
    if (g.fx) g.fx.burst(muzzle, 0xbfffe9, 8, 0.7, new Vector3());
    return true;
  }

  spawnProjectile(origin, dir) {
    const group = new Group();
    const coreMat = new MeshBasicMaterial({ color: 0xe8fff7, toneMapped: false });
    const glowMat = new MeshBasicMaterial({ color: 0x79ffd9, transparent: true, opacity: 0.75, blending: AdditiveBlending, depthWrite: false, toneMapped: false });
    const core = new Mesh(new CapsuleGeometry(0.035, 0.45, 3, 6), coreMat);
    core.rotation.x = Math.PI / 2;
    const glow = new Mesh(new SphereGeometry(0.14, 8, 6), glowMat);
    const sprite = new Sprite(new SpriteMaterial({
      map: TEX.glow,
      color: 0x8bffe2,
      transparent: true,
      opacity: 0.8,
      blending: AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    }));
    sprite.scale.set(0.9, 0.9, 1);
    group.add(core, glow, sprite);
    group.position.copy(origin);
    group.quaternion.setFromUnitVectors(Z, dir.clone().normalize());
    group.renderOrder = 10;
    this.scene.add(group);
    this.projectiles.push({
      mesh: group,
      dir: dir.clone().normalize(),
      pos: origin.clone(),
      life: 1.8,
      speed: 88,
      trailTimer: 0,
    });
  }

  update(dt) {
    if (this.cooldown > 0) this.cooldown -= dt;
    if (this.muzzleTime > 0) {
      this.muzzleTime -= dt;
      if (this.muzzleTime <= 0) this.muzzleFlash.visible = false;
    }
    if (this.reloading) {
      this.reloadTime -= dt;
      if (this.reloadTime <= 0) {
        this.reloading = false;
        const need = this.magSize - this.ammo;
        const take = Math.min(need, this.reserve);
        this.ammo += take;
        this.reserve -= take;
        this.game.audio?.tone?.(760, 0.1, 0.04, 'sine', 1.2, 0.2);
      }
    }
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.life -= dt;
      const prevPos = p.pos.clone();
      p.pos.addScaledVector(p.dir, p.speed * dt);
      p.mesh.position.copy(p.pos);
      if (p.life <= 0) {
        this.removeProjectile(i);
        continue;
      }
      // swept creature collision prevents fast bolts from tunnelling at low frame rates
      const hit = this.game.creatures.segmentHit(prevPos, p.pos);
      if (hit) {
        const c = hit.creature;
        c.hit(20, hit.point.clone(), this.game);
        this.game.audio.hitCreature();
        this.game.fx.burst(hit.point, 0xbfffea, 14, 1.2);
        this.game.hitMarker();
        this.removeProjectile(i);
        continue;
      }
      // planet ground / orbit collision
      const planet = this.game.currentPlanet;
      const rel = _to.copy(p.pos).sub(planet.center);
      const dist = rel.length();
      if (dist < planet.radius * 2.5) {
        const dirTo = _dir.copy(rel).normalize();
        const ground = planet.terrain.heightAt(dirTo);
        if (dist <= ground + 0.15) {
          this.game.audio.impact();
          this.game.fx.burst(p.pos, 0xd9fff4, 8, 0.7);
          this.removeProjectile(i);
        }
      }
    }
  }

  removeProjectile(idx) {
    const p = this.projectiles[idx];
    if (!p) return;
    this.scene.remove(p.mesh);
    p.mesh.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) o.material.dispose();
    });
    this.projectiles.splice(idx, 1);
  }

  clear() {
    for (let i = this.projectiles.length - 1; i >= 0; i--) this.removeProjectile(i);
  }
}

